const aiText = $json.output || "";

if (!aiText.trim()) {
  throw new Error("Test_condition_generator không trả về dữ liệu.");
}

let cleanText = aiText
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

try {
  const parsed = JSON.parse(cleanText);

  if (!Array.isArray(parsed.conditions)) {
    throw new Error('Field "conditions" không phải array.');
  }

  return [
    {
      json: parsed
    }
  ];

} catch (error) {
  throw new Error(
    "Không parse được JSON từ Test_condition_generator: " +
    error.message +
    "\n\nRAW OUTPUT:\n" +
    cleanText
  );
}

const items = $input.all();

if (items.length === 0) {
  return [];
}

// ==============================================
// GROUP TESTCASE THEO TEST SUITE
// ==============================================

const groups = new Map();

for (const item of items) {
  const tc = item.json;

  const suite =
    tc.test_suite && String(tc.test_suite).trim()
      ? String(tc.test_suite).trim()
      : "General";

  if (!groups.has(suite)) {
    groups.set(suite, []);
  }

  groups.get(suite).push(tc);
}


// ==============================================
// TẠO OUTPUT:
// Suite
// TC
// TC
// Suite
// TC
// ==============================================

const result = [];

for (const [suite, testcases] of groups.entries()) {

  // Dòng Test Suite
  result.push({
    json: {
      row_type: "suite",
      test_suite: suite,
      muc_dich: suite,
      cac_buoc: "",
      ket_qua_mong_muon: ""
    }
  });

  // Các testcase thuộc suite
  for (const tc of testcases) {
    result.push({
      json: {
        row_type: "testcase",
        test_suite: suite,
        muc_dich: tc.muc_dich || "",
        cac_buoc: tc.cac_buoc || "",
        ket_qua_mong_muon: tc.ket_qua_mong_muon || ""
      }
    });
  }
}

return result;

